def conjugate(verb):
    conjugations = {
        "ar": ["o", "as", "a", "amos", "ais", "an"],
        "er": ["o", "es", "e", "emos", "eis", "en"],
        "ir": ["o", "es", "e", "imos", "is", "en"]
    }

    base = verb[:-2]
    suffix = verb[-2:]

    if suffix not in conjugations:
        return None

    conjugated_forms = [base + s for s in conjugations[suffix]]

    return {verb: conjugated_forms}
